/*
 * loader.js — gets formations + plays into the app, then resolves them.
 *
 * Two sources, because Plash may load the page from file:// where fetch()
 * of local JSON is blocked:
 *
 *   1. http(s)://  → fetch src/data/manifest.json and every file it lists.
 *   2. file://     → plays.bundle.js (generated by tools/bundle-data.mjs),
 *                    which calls FD.Data.register({ formations, plays }).
 *
 * Every play passes through FD.Resolve (formation + vocabulary + validation).
 * A play with fatal problems is skipped; the wallpaper keeps running.
 */
window.FD = window.FD || {};
(function (FD) {
  'use strict';

  const BASE = 'src/data/';
  let bundled = null;

  async function fetchJson(url) {
    const res = await fetch(url, { cache: 'no-cache' });
    if (!res.ok) throw new Error(`${url}: HTTP ${res.status}`);
    return res.json();
  }

  const Data = {
    /** Called by plays.bundle.js. */
    register(payload) {
      bundled = payload;
    },

    async load() {
      let payload = null;
      if (/^https?:/.test(location.protocol)) {
        try {
          const manifest = await fetchJson(`${BASE}manifest.json`);
          const formations = [];
          for (const f of manifest.formations || []) formations.push(await fetchJson(BASE + f));
          const plays = [];
          for (const f of manifest.plays || []) {
            const json = await fetchJson(BASE + f);
            plays.push(...(Array.isArray(json) ? json : [json]));
          }
          const concepts = [];
          for (const f of manifest.concepts || []) concepts.push(await fetchJson(BASE + f));
          payload = { formations, concepts, plays };
        } catch (err) {
          console.warn('[data] fetch failed, falling back to bundle:', err.message);
        }
      }
      if (!payload) payload = bundled;
      if (!payload || !((payload.plays || []).length || (payload.concepts || []).length)) {
        throw new Error('No play data found. Run "node tools/bundle-data.mjs", or serve this folder over http.');
      }
      return Data.accept(payload);
    },

    accept(payload) {
      const formations = {};
      for (const f of payload.formations || []) formations[f.id] = f;

      const ok = [];
      Data.report = [];
      // Concept templates expand into ordinary plays (one per presentation).
      const all = [];
      for (const c of payload.concepts || []) {
        const { plays, errors } = FD.Concepts.expand(c, formations);
        all.push(...plays);
        for (const e of errors) {
          Data.report.push({ id: e.id, fatal: [e.message], warn: [] });
          console.error(`[data] skipping ${e.id}:`, e.message);
        }
      }
      all.push(...(payload.plays || []));
      all.forEach((raw, i) => {
        const { play, fatal, warn } = FD.Resolve.resolve(raw, formations);
        Data.report.push({ id: raw.id, fatal, warn });
        if (fatal.length) {
          console.error(`[data] skipping ${raw.id}:`, fatal);
          return;
        }
        if (warn.length) console.warn(`[data] ${raw.id}:`, warn);
        if (play.number === undefined) play.number = i + 1;
        ok.push(play);
      });
      if (!ok.length) throw new Error('Every play failed validation. See the console for details.');
      return ok;
    },
  };

  FD.Data = Data;
})(window.FD);
